这是为您实现的《逆转三国》网页版游戏HTML代码。它是一个基于卡牌对战和资源管理的策略小游戏。
```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>逆转三国 · 网页版</title>
  <style>
    * {
      box-sizing: border-box;
      user-select: none;
    }

    body {
      margin: 0;
      min-height: 100vh;
      background: linear-gradient(145deg, #1e2b3a 0%, #0e1a26 100%);
      font-family: 'Segoe UI', 'PingFang SC', Roboto, 'Helvetica Neue', sans-serif;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 16px;
    }

    .game-container {
      background: #2d3e4f;
      padding: 24px 28px 28px;
      border-radius: 56px 56px 48px 48px;
      box-shadow: 0 20px 30px rgba(0, 0, 0, 0.7), inset 0 1px 4px rgba(255, 255, 255, 0.1);
      border: 1px solid #6b8b9c;
    }

    .game-panel {
      background: #1c2a36;
      border-radius: 40px;
      padding: 24px 20px 20px;
      box-shadow: inset 0 0 0 1px #35505e, inset 0 8px 12px rgba(0, 0, 0, 0.5);
    }

    .header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding: 0 8px 16px 8px;
      color: #d4e9ff;
      text-shadow: 0 2px 0 #0a1219;
      font-weight: 600;
      letter-spacing: 1px;
    }

    .title {
      font-size: 22px;
      background: linear-gradient(to bottom, #f3e9c0, #c9a86b);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
      filter: drop-shadow(0 2px 2px black);
    }

    .score {
      background: #0b1a24;
      padding: 8px 20px;
      border-radius: 40px;
      box-shadow: inset 0 2px 5px #00000066, 0 2px 0 #4e6d7e;
      font-size: 18px;
      display: flex;
      align-items: center;
      gap: 8px;
      color: #ffd966;
      border: 1px solid #6b8b9c;
    }

    .score span {
      color: #f0f9ff;
      font-size: 14px;
      opacity: 0.9;
    }

    .battlefield {
      display: flex;
      gap: 16px;
      justify-content: center;
      margin-bottom: 24px;
    }

    .team-area {
      flex: 1;
      display: flex;
      flex-direction: column;
      gap: 16px;
      min-width: 220px;
    }

    .enemy-area {
      flex: 1;
      display: flex;
      flex-direction: column;
      gap: 16px;
      min-width: 220px;
    }

    .panel-label {
      font-size: 14px;
      font-weight: 600;
      color: #96b8d0;
      margin-bottom: 4px;
      padding-left: 8px;
      text-transform: uppercase;
      letter-spacing: 1px;
      text-shadow: 0 1px 0 #0a1219;
    }

    .cards-row {
      display: flex;
      gap: 12px;
      justify-content: center;
      flex-wrap: wrap;
    }

    .card {
      width: 86px;
      height: 118px;
      background: #223645;
      border-radius: 16px;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      padding: 6px 2px;
      box-shadow: 0 8px 0 #0b141c, 0 12px 16px rgba(0, 0, 0, 0.6);
      border: 2px solid #4e6d7e;
      transition: all 0.08s ease;
      cursor: pointer;
      position: relative;
      font-weight: 700;
    }

    .card:active {
      transform: translateY(6px);
      box-shadow: 0 2px 0 #0b141c, 0 8px 12px rgba(0, 0, 0, 0.6);
    }

    .card.selected {
      border: 3px solid #ffcf4a;
      box-shadow: 0 0 0 3px #ffd966cc, 0 8px 0 #0b141c, 0 12px 16px black;
      transform: translateY(-3px);
    }

    .card.disabled {
      filter: grayscale(0.8) brightness(0.5);
      pointer-events: none;
      opacity: 0.6;
      transform: translateY(4px);
      box-shadow: 0 4px 0 #0b141c, 0 6px 10px rgba(0, 0, 0, 0.6);
    }

    .card .name {
      font-size: 13px;
      color: #ffecbb;
      text-align: center;
      line-height: 1.2;
      margin-top: 4px;
      text-shadow: 0 1px 0 black;
    }

    .card .power {
      font-size: 24px;
      color: #f5e56b;
      text-shadow: 0 2px 0 #4a3e1a, 0 0 8px #ffbb33;
      margin-top: 2px;
      font-weight: 800;
    }

    .card .hp-bar {
      width: 70%;
      height: 6px;
      background: #1b2d3a;
      border-radius: 10px;
      margin-top: 6px;
      overflow: hidden;
      box-shadow: inset 0 1px 3px black;
    }

    .card .hp-fill {
      height: 100%;
      width: 100%;
      background: #5ac86b;
      border-radius: 10px;
      box-shadow: 0 0 8px #7ef07e;
    }

    .card.enemy .hp-fill {
      background: #d64545;
      box-shadow: 0 0 8px #ff6b6b;
    }

    .card .hp-text {
      font-size: 10px;
      color: #bdd4e8;
      margin-top: 2px;
      letter-spacing: 0.5px;
    }

    .action-bar {
      display: flex;
      justify-content: center;
      gap: 16px;
      margin-top: 16px;
      padding: 8px 0;
    }

    .btn {
      background: #2e4b5e;
      border: none;
      border-radius: 60px;
      padding: 14px 32px;
      font-weight: 700;
      font-size: 18px;
      color: #fff3d1;
      text-shadow: 0 2px 0 #1e2b36;
      box-shadow: 0 8px 0 #0f1a22, 0 10px 18px black;
      cursor: pointer;
      transition: all 0.08s ease;
      letter-spacing: 1px;
      border: 1px solid #7fa7bb;
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .btn:active {
      transform: translateY(6px);
      box-shadow: 0 2px 0 #0f1a22, 0 6px 12px black;
    }

    .btn:disabled {
      opacity: 0.4;
      transform: translateY(4px);
      box-shadow: 0 4px 0 #0f1a22, 0 8px 12px black;
      pointer-events: none;
      filter: grayscale(0.5);
    }

    .btn.reset {
      background: #4a3f2c;
      border-color: #b89b6e;
      color: #ffdcaa;
      box-shadow: 0 8px 0 #2a2218, 0 10px 18px black;
    }

    .message {
      text-align: center;
      padding: 12px 16px;
      background: #0a151f;
      border-radius: 40px;
      color: #b3d9ff;
      font-weight: 600;
      margin-top: 16px;
      border: 1px solid #3e6277;
      box-shadow: inset 0 2px 8px black;
      font-size: 15px;
      min-height: 52px;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .vs-divider {
      display: flex;
      flex-direction: column;
      justify-content: center;
      align-items: center;
      font-size: 28px;
      font-weight: 900;
      color: #afc9db;
      text-shadow: 0 4px 0 #0b141c, 0 0 20px #6fa3c0;
      padding: 0 8px;
    }
  </style>
</head>
<body>
<div class="game-container">
  <div class="game-panel">
    <div class="header">
      <div class="title">⚔️ 逆转三国 ⚔️</div>
      <div class="score">
        <span>战功</span> <span id="scoreDisplay">0</span>
      </div>
    </div>

    <div class="battlefield">
      <!-- 我方队伍 -->
      <div class="team-area">
        <div class="panel-label">🇨🇳 我方部队</div>
        <div class="cards-row" id="playerCards"></div>
      </div>

      <!-- VS 装饰 -->
      <div class="vs-divider">VS</div>

      <!-- 敌方队伍 -->
      <div class="enemy-area">
        <div class="panel-label">🏴 敌方部队</div>
        <div class="cards-row" id="enemyCards"></div>
      </div>
    </div>

    <div class="action-bar">
      <button class="btn" id="attackBtn" disabled>⚡ 进攻</button>
      <button class="btn reset" id="resetBtn">🔄 重整旗鼓</button>
    </div>

    <div class="message" id="messageBox">
      点击我方武将，再点击敌方目标发起攻击
    </div>
  </div>
</div>

<script>
  (function() {
    // ----- 游戏数据模型 -----
    // 武将基础数据 (名称, 攻击力, 生命值)
    const HEROES = [
      { name: '关羽', atk: 5, maxHp: 10 },
      { name: '张飞', atk: 6, maxHp: 9 },
      { name: '赵云', atk: 4, maxHp: 12 }
    ];

    const ENEMIES = [
      { name: '吕布', atk: 7, maxHp: 12 },
      { name: '华雄', atk: 4, maxHp: 10 },
      { name: '张辽', atk: 5, maxHp: 11 }
    ];

    // 游戏状态
    let playerTeam = [];      // 我方武将对象数组 { name, atk, maxHp, hp, alive }
    let enemyTeam = [];       // 敌方武将对象数组
    let selectedHeroIndex = -1; // 当前选中的我方武将索引
    let score = 0;            // 累计战功 (击杀数/总伤害? 这里每击败一个敌人+1)
    let gameOver = false;     // 是否结束(全灭或胜利)
    let message = '点击我方武将，再点击敌方目标发起攻击';

    // DOM 元素
    const playerCardsDiv = document.getElementById('playerCards');
    const enemyCardsDiv = document.getElementById('enemyCards');
    const attackBtn = document.getElementById('attackBtn');
    const resetBtn = document.getElementById('resetBtn');
    const messageBox = document.getElementById('messageBox');
    const scoreDisplay = document.getElementById('scoreDisplay');

    // ----- 辅助函数 -----
    function deepCopyHeroes(heroList) {
      return heroList.map(h => ({
        name: h.name,
        atk: h.atk,
        maxHp: h.maxHp,
        hp: h.maxHp,
        alive: true
      }));
    }

    // 重置游戏
    function resetGame() {
      playerTeam = deepCopyHeroes(HEROES);
      enemyTeam = deepCopyHeroes(ENEMIES);
      selectedHeroIndex = -1;
      score = 0;
      gameOver = false;
      updateMessage('点击我方武将，再点击敌方目标发起攻击');
      render();
    }

    // 更新消息
    function updateMessage(msg) {
      message = msg;
      messageBox.textContent = message;
    }

    // 检查游戏状态
    function checkGameState() {
      const playerAlive = playerTeam.some(h => h.alive);
      const enemyAlive = enemyTeam.some(e => e.alive);

      if (!playerAlive) {
        gameOver = true;
        updateMessage('💀 我军覆灭... 点击「重整旗鼓」再战');
      } else if (!enemyAlive) {
        gameOver = true;
        updateMessage('🎉 大获全胜！ 点击「重整旗鼓」继续征战');
      } else {
        gameOver = false;
      }

      // 如果游戏结束，取消选中状态
      if (gameOver) {
        selectedHeroIndex = -1;
      }
    }

    // 敌方回合：每个存活的敌人随机攻击一名存活的我方武将
    function enemyTurn() {
      const aliveEnemies = enemyTeam.filter(e => e.alive);
      if (aliveEnemies.length === 0) return;

      const alivePlayers = playerTeam.filter(p => p.alive);
      if (alivePlayers.length === 0) return; // 已经输了，不需攻击

      // 每个敌人发动一次攻击
      aliveEnemies.forEach(enemy => {
        // 找到所有存活的我方索引
        const aliveIndices = playerTeam.reduce((acc, hero, idx) => {
          if (hero.alive) acc.push(idx);
          return acc;
        }, []);
        if (aliveIndices.length === 0) return;

        const randomIdx = aliveIndices[Math.floor(Math.random() * aliveIndices.length)];
        const target = playerTeam[randomIdx];
        target.hp = Math.max(0, target.hp - enemy.atk);
        if (target.hp <= 0) {
          target.alive = false;
          target.hp = 0;
        }
      });
    }

    // 执行攻击：选中的我方武将攻击指定的敌方目标
    function performAttack(targetEnemyIndex) {
      // 合法性检查
      if (gameOver) {
        updateMessage('战斗已经结束，请点击重整旗鼓');
        return;
      }
      if (selectedHeroIndex === -1) {
        updateMessage('请先选择一名我方武将');
        return;
      }
      const hero = playerTeam[selectedHeroIndex];
      if (!hero.alive) {
        updateMessage('该武将已阵亡，请选择其他武将');
        selectedHeroIndex = -1;
        render();
        return;
      }

      const targetEnemy = enemyTeam[targetEnemyIndex];
      if (!targetEnemy.alive) {
        updateMessage('目标已经阵亡，请选择其他敌人');
        return;
      }

      // 记录攻击前敌方血量
      const beforeHp = targetEnemy.hp;
      // 攻击
      targetEnemy.hp = Math.max(0, targetEnemy.hp - hero.atk);
      const damageDealt = beforeHp - targetEnemy.hp;

      let killMessage = '';
      if (targetEnemy.hp <= 0) {
        targetEnemy.alive = false;
        targetEnemy.hp = 0;
        score += 1;
        killMessage = ` 击败了 ${targetEnemy.name}！`;
      }

      // 更新消息
      updateMessage(`⚔️ ${hero.name} 对 ${targetEnemy.name} 造成 ${damageDealt} 点伤害。${killMessage}`);

      // 清除选中状态
      selectedHeroIndex = -1;

      // 检查我方或敌方是否全灭 (攻击后可能敌方全灭)
      checkGameState();
      if (gameOver) {
        render();
        return;
      }

      // 敌方反击 (如果游戏还没结束)
      if (!gameOver) {
        enemyTurn();
        // 再次检查状态 (敌方攻击可能导致我方全灭)
        checkGameState();
      }

      // 重新渲染界面
      render();
    }

    // ----- 渲染界面 -----
    function render() {
      // 渲染玩家卡牌
      renderTeam(playerCardsDiv, playerTeam, 'player');
      // 渲染敌人卡牌
      renderTeam(enemyCardsDiv, enemyTeam, 'enemy');

      // 更新战功显示
      scoreDisplay.textContent = score;

      // 更新攻击按钮状态
      const anyPlayerAlive = playerTeam.some(h => h.alive);
      const anyEnemyAlive = enemyTeam.some(e => e.alive);
      const canAttack = !gameOver && anyPlayerAlive && anyEnemyAlive && selectedHeroIndex !== -1 && playerTeam[selectedHeroIndex]?.alive;

      attackBtn.disabled = !canAttack;

      // 如果游戏结束，修改消息
      if (gameOver) {
        if (!anyPlayerAlive) {
          updateMessage('💀 我军覆灭... 点击「重整旗鼓」再战');
        } else if (!anyEnemyAlive) {
          updateMessage('🎉 大获全胜！ 点击「重整旗鼓」继续征战');
        }
      } else {
        // 非结束状态，保持消息显示即可
        messageBox.textContent = message;
      }
    }

    // 渲染一个队伍 (队伍数组, 类型 'player' 或 'enemy')
    function renderTeam(container, team, type) {
      container.innerHTML = '';
      team.forEach((unit, index) => {
        const card = document.createElement('div');
        card.className = `card ${type} ${!unit.alive ? 'disabled' : ''}`;

        // 如果是玩家队伍且选中了这个武将，加上selected
        if (type === 'player' && selectedHeroIndex === index && unit.alive && !gameOver) {
          card.classList.add('selected');
        }

        // 名字
        const nameDiv = document.createElement('div');
        nameDiv.className = 'name';
        nameDiv.textContent = unit.name;
        card.appendChild(nameDiv);

        // 攻击力
        const powerDiv = document.createElement('div');
        powerDiv.className = 'power';
        powerDiv.textContent = unit.atk;
        card.appendChild(powerDiv);

        // 血条
        const hpBarDiv = document.createElement('div');
        hpBarDiv.className = 'hp-bar';
        const hpFill = document.createElement('div');
        hpFill.className = 'hp-fill';
        const hpPercent = Math.max(0, (unit.hp / unit.maxHp) * 100);
        hpFill.style.width = `${hpPercent}%`;
        hpBarDiv.appendChild(hpFill);
        card.appendChild(hpBarDiv);

        // 血量文本
        const hpText = document.createElement('div');
        hpText.className = 'hp-text';
        hpText.textContent = `${unit.hp}/${unit.maxHp}`;
        card.appendChild(hpText);

        // 点击事件
        if (type === 'player' && unit.alive && !gameOver) {
          card.addEventListener('click', (e) => {
            e.stopPropagation();
            // 点击我方武将：如果已经选中同一个，则取消选中；否则选中
            if (selectedHeroIndex === index) {
              selectedHeroIndex = -1;
              updateMessage('已取消选择');
            } else {
              selectedHeroIndex = index;
              updateMessage(`已选中 ${unit.name}，请点击敌方目标发起攻击`);
            }
            render(); // 刷新选中状态和按钮
          });
        } else if (type === 'enemy' && unit.alive && !gameOver) {
          card.addEventListener('click', (e) => {
            e.stopPropagation();
            // 点击敌人时，如果已选中我方武将，则发起攻击；否则提示
            if (selectedHeroIndex !== -1 && playerTeam[selectedHeroIndex]?.alive) {
              performAttack(index);
            } else {
              updateMessage('请先选择一名存活的我方武将');
            }
          });
        } else if (!unit.alive) {
          // 阵亡卡牌不响应点击
          card.style.pointerEvents = 'none';
        } else if (gameOver) {
          // 游戏结束也不响应点击
          card.style.pointerEvents = 'none';
        }

        container.appendChild(card);
      });
    }

    // 攻击按钮点击：相当于快捷操作，但必须选中武将且敌方有存活，我们自动选择第一个存活的敌人进行攻击
    function onAttackButtonClick() {
      if (selectedHeroIndex === -1) {
        updateMessage('请先选择一名我方武将');
        return;
      }
      const hero = playerTeam[selectedHeroIndex];
      if (!hero.alive) {
        updateMessage('该武将已阵亡');
        selectedHeroIndex = -1;
        render();
        return;
      }
      // 找第一个存活的敌人
      const firstAliveEnemyIndex = enemyTeam.findIndex(e => e.alive);
      if (firstAliveEnemyIndex === -1) {
        // 没有敌人存活，实际上游戏已结束
        checkGameState();
        render();
        return;
      }
      performAttack(firstAliveEnemyIndex);
    }

    // 初始化事件监听
    function init() {
      resetGame();

      attackBtn.addEventListener('click', onAttackButtonClick);

      resetBtn.addEventListener('click', () => {
        resetGame();
      });

      // 点击空白区域取消选中（点击body，但如果点卡牌会阻止冒泡，这里用document处理）
      document.addEventListener('click', (e) => {
        // 如果点击的是按钮或者卡牌，忽略（卡牌自己处理了）
        if (e.target.closest('.card') || e.target.closest('.btn') || e.target.closest('.game-container')) {
          // 如果点击的是容器内部但不在卡牌/按钮上，也可能是背景，但我们希望取消选中? 但为避免干扰，只处理纯背景点击。
          // 但简单起见，如果点的是容器但不是卡牌/按钮，我们也可以取消选中。为了更好的体验，不自动取消选中，以免误触。
          // 这里我们保持：点击卡牌外区域取消选中? 决定不取消，用户可以通过再次点击已选中的卡牌取消。
          // 所以这里什么也不做。
        }
      });
    }

    // 启动
    init();
  })();
</script>
</body>
</html>
```
### 玩法与操作说明
游戏模拟了双方部队的对战，您需要指挥我方武将击败所有敌人。它的核心是选择武将并攻击目标的简单回合制战斗。

- **战斗流程**：游戏开始后，您需要先点击一名我方武将（卡牌会高亮），然后点击一名敌方武将来发动攻击。攻击后，敌方所有存活单位会随机攻击您的一名武将。
- **状态与反馈**：每张卡牌都显示了武将的攻击力和生命值。血条会直观反映生命值变化。屏幕顶部的“战功”会记录您击败的敌将数量，下方的消息框则会提示每一步的操作结果。
- **胜负与重置**：当您消灭所有敌人或我方全部阵亡时，游戏结束。您可以随时点击“重整旗鼓”按钮开始新的一局。
